package com.kasiguru.data.local

import com.kasiguru.data.local.entity.*
import com.kasiguru.util.Constants

/**
 * Complete Kasiguranin Linguistic Corpus DatabaseSeeder.
 * Extracted directly from UP Thesis: A Grammatical Sketch of Kasiguranin (Supnet, 2016).
 * Contains 394 vocabulary entries.
 */
object DatabaseSeeder {

    fun getInitialGameLevels(): List<GameLevelEntity> {
        val levels = mutableListOf<GameLevelEntity>()
        val gameTypes = listOf(
            "word_match", "reverse_match", "fill_blank",
            // Word Recall took this slot over from Audio Quiz and kept its key so existing levels,
            // stars and high scores keep counting — see Constants.Games.RECALL.
            Constants.Games.RECALL,
            "aspect_builder", "sentence_order"
        )
        
        for (game in gameTypes) {
            for (levelNum in 1..30) {
                val difficulty = when (levelNum) {
                    in 1..10 -> "Easy"
                    in 11..20 -> "Medium"
                    else -> "Hard"
                }
                val questionsCount = when (difficulty) {
                    "Easy" -> 5
                    "Medium" -> 10
                    else -> 15
                }
                levels.add(
                    GameLevelEntity(
                        gameType = game,
                        levelNumber = levelNum,
                        difficulty = difficulty,
                        isUnlocked = levelNum == 1, // Only level 1 is unlocked initially
                        questionsCount = questionsCount
                    )
                )
            }
        }
        return levels
    }

        /**
     * The Kasiguranin corpus: 1202 senses.
     *
     * Split across 9 private methods rather than written as one list. A JVM method is
     * capped at 64 KB of bytecode and a corpus this size in a single method does not compile;
     * the split is purely a build constraint and the concatenation order is the corpus order.
     *
     * Generated by scripts/import_wordlist.js. Hand edits survive a re-run -- the importer
     * keeps every existing entry as it stands and only appends senses the corpus lacks.
     */
    fun getInitialVocabulary(): List<VocabularyEntity> =
        vocabularyChunk1() +
        vocabularyChunk2() +
        vocabularyChunk3() +
        vocabularyChunk4() +
        vocabularyChunk5() +
        vocabularyChunk6() +
        vocabularyChunk7() +
        vocabularyChunk8() +
        vocabularyChunk9()

